theorem basis_one {ι : Type _} [Fintype ι] [DecidableEq ι] {B : Basis ι K L} {i : ι}
    (hBi : B i = (1 : L)) (k : K) :
    B.equivFun ((algebraMap K L) k) = fun j : ι => if j = i then k else 0

theorem norm_is_bdd {ι : Type _} [Fintype ι] [Nonempty ι] {B : Basis ι K L} {i : ι}
    (hBi : B i = (1 : L)) (hna : IsNonarchimedean (Norm.norm : K → ℝ)) :
    ∃ (c : ℝ) (_ : 0 < c), ∀ x y : L, B.norm (x * y) ≤ c * B.norm x * B.norm y

theorem norm_smul {ι : Type _} [Fintype ι] [Nonempty ι] {B : Basis ι K L} {i : ι}
    (hBi : B i = (1 : L)) (k : K) (y : L) :
    B.norm ((algebraMap K L) k * y) = B.norm ((algebraMap K L) k) * B.norm y

theorem seminorm_from_bounded_of_mul_apply (f_nonneg : ∀ x : R, 0 ≤ f x)
    (f_mul : ∃ (c : ℝ) (_ : 0 < c), ∀ x y : R, f (x * y) ≤ c * f x * f y) {x : R}
    (hx : ∀ y : R, f (x * y) = f x * f y) : seminormFromBounded' f x = f x

theorem seminorm_from_bounded_ker (f_nonneg : ∀ x : R, 0 ≤ f x)
    (f_mul : ∃ (c : ℝ) (_ : 0 < c), ∀ x y : R, f (x * y) ≤ c * f x * f y) :
    seminormFromBounded' f ⁻¹' {0} = f ⁻¹' {0}

